CREATE TABLE t0 (c2 INTEGER, c5 INTEGER);
SELECT subq1.c13 AS c15, CAST(subq1.c13 AS TEXT) AS c17 FROM (SELECT FALSE AS c13 FROM (SELECT t1.c2 AS c9, t1.c5 AS c11 FROM t0 AS t1 ORDER BY c11 COLLATE NOCASE ASC) AS subq0) AS subq1 WHERE subq1.c13 = CASE subq1.c13 WHEN subq1.c13 = subq1.c13 THEN subq1.c13 ELSE subq1.c13 END OR subq1.c13 = NULLIF(subq1.c13, subq1.c13) ORDER BY c15, c15 ASC LIMIT -1 OFFSET 1